from taf.sbts.oam.coam.admin import admin

from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector
from taf.rfrl.procedures.resources.python.status_check.exceptions import InvalidBBMODvariant


class Bbmod(object):

    _status_selector = StatusSelector()

    def __init__(self, config_id=None, connection=None):
        self.config_id = config_id
        self.connection = connection
        self._hw_type = ''
        self._api = admin()

    def get_expected_statuses(self, variant):
        """
        Returns expected values of statuses for given variant.
        :param variant: variant of expected statuses, can be 'active', 'online', 'disabled', 'degraded', failed,
                       'initializing'.
        :type variant: str
        :return: dictionary with statuses names as keys and expected statuses values as values
        :rtype: dict(str, str)
        :raises InvalidBBMODvariant: if provided variant does not exist
        """
        if variant == 'active':
            return self._get_active_statuses()
        elif variant == 'online':
            return self._get_online_statuses()
        elif variant == 'disabled':
            return self._get_disabled_statuses()
        elif variant == 'degraded':
            return self._get_degraded_statuses()
        elif variant == 'failed':
            return self._get_failed_statuses()
        elif variant == 'initializing':
            return self._get_initializing_statuses()
        else:
            raise InvalidBBMODvariant("Provided BBMOD variant does not exist: {}".format(variant))

    @classmethod
    def _get_active_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='enabled'),
                'administrativeState': cls._status_selector.select_administrative_state(variant='unlocked'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='online'),
                "usageState": "Active",
                'proceduralStatus': 'configured'}

    @classmethod
    def _get_online_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='enabled'),
                'administrativeState': cls._status_selector.select_administrative_state(variant='unlocked'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='online'),
                'proceduralStatus': 'configured'}

    def _get_disabled_statuses(self):
        self._set_hw_type()
        return {'operationalState': self._status_selector.select_operational_state(variant='disabled'),
                'administrativeState': self._status_selector.select_administrative_state(variant='unlocked'),
                'availabilityStatus': self._status_selector.select_availability_status(variant='offline'),
                'proceduralStatus': 'initializing' if 'ABIA' in self._hw_type else 'not initialized'}

    @classmethod
    def _get_degraded_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='enabled'),
                'administrativeState': cls._status_selector.select_administrative_state(variant='unlocked'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='degraded'),
                'proceduralStatus': 'configured'}

    @classmethod
    def _get_failed_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='disabled'),
                'administrativeState': cls._status_selector.select_administrative_state(variant='unlocked'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='failed'),
                'proceduralStatus': 'not initialized'}

    @classmethod
    def _get_initializing_statuses(cls):
        return {'operationalState': cls._status_selector.select_operational_state(variant='disabled'),
                'administrativeState': cls._status_selector.select_administrative_state(variant='unlocked'),
                'availabilityStatus': cls._status_selector.select_availability_status(variant='offline'),
                'proceduralStatus': 'initializing'}

    def _set_hw_type(self):
        info = self._api.get_bts_info(connection=self.connection)['basebandModules'] if self.connection else ''
        for bbmod_info in info:
            try:
                bbmod_id = bbmod_info['id']['configuration'].split("-")[-1]
            except KeyError as e:
                missing_key = e.args[0]
                if missing_key == 'configuration' and bbmod_info['status']['usageState'].lower() == 'idle':
                    continue
                raise

            if bbmod_id == str(self.config_id):
                self._hw_type = bbmod_info['productName']
